const query = $input.first().json.query?.toLowerCase() || $input.first().json.chatInput?.toLowerCase() || '';
const products = staticData.products;

const results = products.filter(p => 
  p.name.toLowerCase().includes(query) || 
  p.category.toLowerCase().includes(query) ||
  p.description.toLowerCase().includes(query)
);

if (results.length === 0) {
  return { result: `Žádné produkty pro "${query}". Kategorie: laptops, phones, headphones, monitors, gaming, accessories, smart-home.` };
}

const formatted = results.map(p => 
  `[ID:${p.id}] ${p.name} | ${p.category} | ${p.price} Kč | ${p.description}`
).join('\n');

return { result: `Nalezeno ${results.length} produkt(ů):\n${formatted}` };

// === ADD PRODUCT TO DATABASE ===
// This tool adds a new product to the persistent database

const staticData = $getWorkflowStaticData('global');

if (!staticData.products) {
  staticData.products = [];
}

let input = $input.first().json.query || $input.first().json.chatInput || '';

try {
  // Try to parse JSON from the input
  let productData;

  // Handle case where input might be wrapped in extra text
  const jsonMatch = input.match(/\{[^}]+\}/);
  if (jsonMatch) {
    productData = JSON.parse(jsonMatch[0]);
  } else {
    productData = JSON.parse(input);
  }

  const newId = staticData.products.length > 0 
    ? Math.max(...staticData.products.map(p => p.id)) + 1 
    : 1;

  const newProduct = {
    id: newId,
    name: productData.name || 'Unknown Product',
    category: productData.category || 'uncategorized',
    price: Number(productData.price) || 0,
    description: productData.description || 'No description'
  };

  staticData.products.push(newProduct);

  return { result: `Product added successfully! [ID:${newProduct.id}] ${newProduct.name} | Category: ${newProduct.category} | Price: $${newProduct.price} | ${newProduct.description}` };
} catch (e) {
  return { result: `Error adding product. Please provide valid JSON with: name, category, price, description. Error: ${e.message}` };
}

// === LIST ALL ELECTRONICS ===

const staticData = $getWorkflowStaticData('global');

if (!staticData.products || staticData.products.length === 0) {
  return { result: 'Databáze je prázdná. Použij add_product pro přidání produktů.' };
}

const products = staticData.products;
const categories = [...new Set(products.map(p => p.category))];

let output = `TechZone Katalog (${products.length} produktů v ${categories.length} kategoriích):\n\n`;

for (const cat of categories.sort()) {
  const catProducts = products.filter(p => p.category === cat);
  output += `--- ${cat.toUpperCase()} (${catProducts.length}) ---\n`;
  for (const p of catProducts) {
    output += `  [ID:${p.id}] ${p.name} - ${p.price} Kč - ${p.description}\n`;
  }
  output += '\n';
}

const totalValue = products.reduce((sum, p) => sum + p.price, 0);
output += `Celková hodnota katalogu: ${totalValue.toLocaleString('cs-CZ')} Kč`;

return { result: output };

// === DELETE PRODUCT FROM DATABASE ===

const staticData = $getWorkflowStaticData('global');

if (!staticData.products || staticData.products.length === 0) {
  return { result: 'The product database is empty. Nothing to delete.' };
}

const input = $input.first().json.query || $input.first().json.chatInput || '';
const id = parseInt(input);

if (isNaN(id)) {
  return { result: `Invalid ID "${input}". Please provide a numeric product ID.` };
}

const index = staticData.products.findIndex(p => p.id === id);

if (index === -1) {
  return { result: `Product with ID ${id} not found.` };
}

const deleted = staticData.products.splice(index, 1)[0];
return { result: `Deleted product: [ID:${deleted.id}] ${deleted.name} ($${deleted.price})` };
